package Tv4.View;
import MainPage.View.Workspace;import javax.swing.*;import java.awt.*;import java.awt.datatransfer.*;import java.util.List;import java.util.function.*;
/** Chỉ dựng lưới, chuyển tiếp sự kiện kéo/thả và menu ngữ cảnh. */
public class ThoiKhoaBieuPage extends Workspace {
 public record ClassItem(int id,String label){public String toString(){return label;}}
 public record SlotItem(int rule,int lesson,int lop,String label){}
 @FunctionalInterface public interface Drop{void accept(int lop,int day,int ca);}
 @FunctionalInterface public interface Menu{void accept(SlotItem item,int day,int ca,int action);}
 private final DefaultListModel<ClassItem> lm=new DefaultListModel<>();private final JList<ClassItem> list=new JList<>(lm);private final JPanel grid=new JPanel();
 public ThoiKhoaBieuPage(){super();JPanel left=new JPanel(new BorderLayout());left.setPreferredSize(new Dimension(220,0));left.add(new JLabel("  Danh sách lớp — kéo vào lịch"),BorderLayout.NORTH);left.add(new JScrollPane(list));JPanel all=new JPanel(new BorderLayout(8,8));all.add(left,BorderLayout.WEST);all.add(new JScrollPane(grid),BorderLayout.CENTER);content(all);list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);list.setDragEnabled(!GraphicsEnvironment.isHeadless());list.setTransferHandler(new TransferHandler(){public int getSourceActions(JComponent c){return COPY;}protected Transferable createTransferable(JComponent c){ClassItem x=list.getSelectedValue();return x==null?null:new StringSelection(String.valueOf(x.id()));}});}
 public void classes(List<ClassItem> items){lm.clear();items.forEach(lm::addElement);}
 public int selectedClass(){ClassItem x=list.getSelectedValue();return x==null?0:x.id();}
 public void classMenu(IntConsumer event){JPopupMenu m=new JPopupMenu();for(int i=0;i<2;i++){int n=i;JMenuItem item=new JMenuItem(i==0?"Xem thông tin":"Xóa lớp");item.addActionListener(e->event.accept(n));m.add(item);}list.addMouseListener(new java.awt.event.MouseAdapter(){void show(java.awt.event.MouseEvent e){if(e.isPopupTrigger()){int i=list.locationToIndex(e.getPoint());if(i>=0&&list.getCellBounds(i,i).contains(e.getPoint())){list.setSelectedIndex(i);m.show(list,e.getX(),e.getY());}}}public void mousePressed(java.awt.event.MouseEvent e){show(e);}public void mouseReleased(java.awt.event.MouseEvent e){show(e);}});}
 public void grid(String[] days,String[] shifts,int[] ids,List<SlotItem>[][] cells,Drop drop,Menu menu){grid.removeAll();grid.setLayout(new GridLayout(shifts.length+1,days.length+1,3,3));grid.setBackground(LINE);grid.add(new JLabel("  Ca học"));for(String d:days){JLabel l=new JLabel(d,SwingConstants.CENTER);l.setOpaque(true);l.setBackground(GREEN);grid.add(l);}for(int r=0;r<shifts.length;r++){JLabel l=new JLabel(shifts[r]);l.setOpaque(true);l.setBackground(GREEN);grid.add(l);for(int c=0;c<days.length;c++){int day=c,ca=ids[r];JPanel cell=new JPanel();cell.setLayout(new BoxLayout(cell,BoxLayout.Y_AXIS));cell.setBackground(Color.WHITE);cell.setPreferredSize(new Dimension(150,115));cell.setTransferHandler(new TransferHandler(){public boolean canImport(TransferSupport s){return s.isDataFlavorSupported(DataFlavor.stringFlavor);}public boolean importData(TransferSupport s){try{if(!canImport(s))return false;drop.accept(Integer.parseInt((String)s.getTransferable().getTransferData(DataFlavor.stringFlavor)),day,ca);return true;}catch(Exception e){return false;}}});JButton add=button("+ Xếp lớp");add.addActionListener(e->{int id=selectedClass();if(id>0)drop.accept(id,day,ca);});cell.add(add);for(SlotItem item:cells[r][c]){JButton b=button(item.label());b.setAlignmentX(Component.LEFT_ALIGNMENT);b.setToolTipText(item.label());b.setMaximumSize(new Dimension(Integer.MAX_VALUE,35));b.addActionListener(e->menu.accept(item,day,ca,0));JPopupMenu pop=new JPopupMenu();String[] labels={"Xem thông tin","Tạo / kích hoạt buổi","Xóa buổi (hủy)","Ngừng lịch lặp"};for(int i=0;i<labels.length;i++){int n=i;JMenuItem mi=new JMenuItem(labels[i]);mi.setEnabled(i!=2||item.lesson()>0);if(i==3)mi.setEnabled(item.rule()>0);mi.addActionListener(e->menu.accept(item,day,ca,n));pop.add(mi);}b.setComponentPopupMenu(pop);cell.add(b);}grid.add(cell);}}grid.revalidate();grid.repaint();}
}
